import {CRISBridge as bridge} from './integration-bridge.js';
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export async function mountCaseBoards(identity, excluded = new Set()){
 const host=document.getElementById('caseBoards');if(!host)return;host.innerHTML='<div class="case-boards-head"><div><span class="micro-label">QUADROS DO CASO</span><h3>Quadros independentes</h3><p>Consulte as pistas liberadas, mesmo fora da sessão.</p></div>'+ (identity.isMaster?'<button type="button" data-new>Novo quadro</button>':'')+'</div><p role="status">Carregando quadros…</p><div class="case-boards-list"></div>';
 let lib;const status=host.querySelector('[role=status]'),list=host.querySelector('.case-boards-list');
 const refresh=async()=>{const all=await lib.list(identity.isMaster),rows=all.filter(board=>!excluded.has(board.id)),publications=identity.isMaster?await lib.list(false):rows,published=new Set(publications.map(b=>b.id));list.innerHTML=rows.map(b=>`<article class="case-board-card"><span class="micro-label">${published.has(b.id)?'DISPONÍVEL AOS AGENTES':'RASCUNHO · SOMENTE MESTRE'}</span><h4>${esc(b.title)}</h4><p>${esc(b.description)}</p><div><a href="quadro/?board=${b.id}">${identity.isMaster?'Preparar quadro':'Abrir quadro'} ↗</a>${identity.isMaster?`<button type="button" data-edit="${b.id}">Detalhes</button>${published.has(b.id)?`<button type="button" data-hide="${b.id}">Recolher publicação</button>`:''}`:''}</div></article>`).join('');status.textContent=rows.length?'':identity.isMaster?'Crie um quadro para uma cena do crime, um conjunto de registros ou outro caso.':'Nenhum quadro independente disponível.';list.querySelectorAll('[data-hide]').forEach(b=>b.onclick=()=>run(async()=>{await lib.unpublish(b.dataset.hide);await refresh();}));list.querySelectorAll('[data-edit]').forEach(b=>b.onclick=()=>editor(rows.find(r=>r.id===b.dataset.edit)));
 if(identity.isMaster)document.querySelectorAll('[data-linked-board]').forEach(slot=>{
   const row=all.find(board=>board.id===slot.dataset.linkedBoard);
   if(!row)return;
   slot.innerHTML='<details class="archive-admin"><summary>Gerenciar quadro</summary><div class="case-archive-actions"><button type="button" data-linked-edit>Detalhes</button>'+
     (published.has(row.id)?'<button type="button" data-linked-hide>Recolher publicação</button>':'')+'</div></details>';
   slot.querySelector('[data-linked-edit]').onclick=()=>editor(row);
   slot.querySelector('[data-linked-hide]')?.addEventListener('click',()=>run(async()=>{await lib.unpublish(row.id);await refresh();}));
 });
 };
 const run=async fn=>{try{await fn();}catch(e){status.textContent=e.message;}};
 const editor=row=>{const dialog=document.createElement('dialog');dialog.className='case-board-dialog';dialog.innerHTML=`<form><h3>${row?'Detalhes do quadro':'Novo quadro de investigação'}</h3><label>Nome<input name="title" required maxlength="120" value="${esc(row?.title)}" placeholder="Ex.: Os nove casos"></label><label>Descrição<textarea name="description" maxlength="2000" rows="3">${esc(row?.description)}</textarea></label><p>O quadro começa em rascunho. Libere aos agentes pelo menu do quadro.</p><p role="status"></p><div><button type="button" data-cancel>Cancelar</button><button type="submit">${row?'Salvar detalhes':'Criar e preparar'}</button></div></form>`;dialog.querySelector('[data-cancel]').onclick=()=>dialog.close();dialog.onclose=()=>dialog.remove();dialog.querySelector('form').onsubmit=async e=>{e.preventDefault();const f=e.currentTarget,b=f.querySelector('[type=submit]');b.disabled=true;try{const data=new FormData(f),title=String(data.get('title')).trim();if(!title)throw Error('Dê um nome ao quadro.');if(row){await lib.rename(row.id,title,String(data.get('description')));dialog.close();await refresh();}else{const id=await lib.create(title,String(data.get('description')));location.href='quadro/?board='+id;}}catch(error){f.querySelector('[role=status]').textContent=error.message;b.disabled=false;}};document.body.append(dialog);dialog.showModal();};
 host.querySelector('[data-new]')?.addEventListener('click',()=>editor());await run(async()=>{lib=await bridge.boardLibrary();await refresh();});
}
